if(!$cotizacionId || $revision===false || $revision===null) die('Revisión inválida.');
$st=$conexion->prepare("SELECT r.*,c.cotizacion_numero,c.fecha_creacion,cl.clientes_codigo,cl.clientes_nomfantasia,cl.clientes_emails,cl.clientes_telefono,COALESCE(u.usuario_nombre,r.usuario,'') responsable FROM cotizaciones_revisiones r JOIN cotizaciones c ON c.cotizacion_id=r.cotizacion_id LEFT JOIN clientes cl ON cl.clientes_id=r.cliente_id LEFT JOIN usuarios u ON u.usuario_id=r.usuario_id WHERE r.cotizacion_id=? AND r.revision=?");
$st->bind_param('ii',$cotizacionId,$revision);$st->execute();$r=$st->get_result()->fetch_assoc();$st->close();if(!$r)die('La revisión solicitada no existe.');
$st=$conexion->prepare('SELECT * FROM cotizaciones_revisiones_detalle WHERE revision_id=? ORDER BY orden_visual');$st->bind_param('i',$r['revision_id']);$st->execute();$d=$st->get_result();
