?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($etiquetaVersion)?> - <?=e(numeroDocumentoVisible($r['cotizacion_numero']))?></title><link rel="stylesheet" href="automac-ui.css"><style>.doc{max-width:1320px;margin:0 auto;background:#fff;border:1px solid #dbe4ea;border-radius:18px;padding:24px}.revision-banner{background:#fff3cd;border:1px solid #ffdf7e;padding:13px 16px;border-radius:12px;margin:14px 0}.datos{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:18px 0}.dato{background:#f5f8fa;border:1px solid #dfe8ed;border-radius:10px;padding:11px}.tabla-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #dde6eb;text-align:left;vertical-align:top}th{background:#203443;color:#fff}.totales{margin-left:auto;max-width:420px;margin-top:18px}.totales div{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid #e1e8ec}.total{font-size:24px;color:#087f4b}.btn-volver{display:inline-block;background:#203443;color:#fff;text-decoration:none;padding:10px 14px;border-radius:9px;font-weight:700}@media(max-width:800px){.datos{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/menu.php';?><main class="doc"><a class="btn-volver" href="ver_cotizacion.php?id=<?=$cotizacionId?>">← Volver a la cotización</a> <a class="btn-volver" style="background:#087f4b" target="_blank" href="generar_pdf_revision.php?tipo=cotizacion&id=<?=$cotizacionId?>&revision=<?=$revision?>">Ver PDF de esta revisión</a><?php envioDocRender($envioDoc); ?><div class="revision-banner"><strong>Vista histórica:</strong> cotización <?=e(numeroDocumentoVisible($r['cotizacion_numero']))?> — <?=e($etiquetaVersion)?>. Esta información es de solo lectura.</div><h1>Detalle de <?=e(strtolower($etiquetaVersion))?></h1><div class="datos"><div class="dato"><b>Cliente</b><br><?=e(($r['clientes_codigo']?:'—').' — '.($r['clientes_nomfantasia']?:'—'))?></div><div class="dato"><b>Solicitante</b><br><?=e($solicitanteCliente!==''?$solicitanteCliente:'—')?></div><div class="dato"><b>Referencia</b><br><?=e($r['referencia']?:'—')?></div><div class="dato"><b>Base de precios</b><br><?=e($r['lista_nombre'])?><?=!empty($r['lista_fecha'])?' · '.e($r['lista_fecha']):''?></div><div class="dato"><b>Estado</b><br><?=e($r['estado'])?></div><div class="dato"><b>Responsable comercial</b><br><?=e($r['responsable']?:'—')?></div><div class="dato"><b>Fecha de esta versión</b><br><?=e(fechaHoraAr($fechaVersionHistorica))?></div><div class="dato" style="grid-column:1/-1"><b>Motivo</b><br><?=nl2br(e($motivoVersion))?></div></div><div class="tabla-wrap"><table><tr><th>Módulo</th><th>Concepto</th><th>Código</th><th>Descripción</th><th>Cantidad</th><th>Unitario</th><th>Fórmula</th><th>Total</th></tr><?php while($x=$d->fetch_assoc()):?><tr><td><?=e($x['modulo'])?></td><td><?=e($x['concepto'])?></td><td><?=e($x['codigo'])?></td><td><?=e(descripcionPresentacionRondMetal($x['descripcion']))?></td><td><?=number_format((float)$x['cantidad'],2,',','.')?></td><td>$<?=number_format(ceil((float)$x['precio_unitario']),0,',','.')?></td><td><?=e($x['formula_aplicada'])?></td><td>$<?=number_format(ceil((float)$x['importe_total']),0,',','.')?></td></tr><?php endwhile;?></table></div><div class="totales"><div><span>Subtotal</span><b>$<?=number_format(ceil((float)$r['subtotal']),0,',','.')?></b></div><div><span>Descuento 1</span><b><?=number_format((float)$r['descuento_1'],2,',','.')?>%</b></div><div><span>Descuento 2</span><b><?=number_format((float)$r['descuento_2'],2,',','.')?>%</b></div><div><span>Descuento 3</span><b><?=number_format((float)$r['descuento_3'],2,',','.')?>%</b></div><div class="total"><span>Total histórico</span><b>$<?=number_format(ceil((float)$r['total']),0,',','.')?></b></div></div></main></body></html>
